    { const char * tb_v925 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v925; }
    { const char * tb_v926 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v926; }
    { const char * tb_v927 = "// p во временной памяти текущей (самой внутренней) области, а не во внешней\n"; *(const char * *)tb_grow(v_lines) = tb_v927; }
    { const char * tb_v928 = "static int tb_in_cur_temp(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v928; }
    { const char * tb_v929 = "    if (tb_temp_depth == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v929; }
