    { const char * tb_v936 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v936; }
    { const char * tb_v937 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v937; }
    { const char * tb_v938 = "// длина последних текстов: s[i] в цикле не пересчитывает strlen каждый раз\n"; *(const char * *)tb_grow(v_lines) = tb_v938; }
    { const char * tb_v939 = "static _Thread_local const char *tb_lc_p[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v939; }
    { const char * tb_v940 = "static _Thread_local long long tb_lc_n[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v940; }
    { const char * tb_v941 = "static _Thread_local int tb_lc_next;\n"; *(const char * *)tb_grow(v_lines) = tb_v941; }
    { const char * tb_v942 = "static inline void tb_lc_clear(void) { tb_lc_p[0] = 0; tb_lc_p[1] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v942; }
    { const char * tb_v943 = "static inline void tb_temp_end(tb_mark m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v943; }
    { const char * tb_v944 = "    // первый кусок оставляем пустым: следующий temp возьмёт его без malloc\n"; *(const char * *)tb_grow(v_lines) = tb_v944; }
