    { const char * tb_v961 = "// Кусок из внешней области (список создан снаружи, растёт внутри temp или шага цикла)\n"; *(const char * *)tb_grow(v_lines) = tb_v961; }
    { const char * tb_v962 = "// переезжает в обычную память: внутренняя область скоро отдаётся, а список живёт дольше.\n"; *(const char * *)tb_grow(v_lines) = tb_v962; }
    { const char * tb_v963 = "static void *tb_resize(void *p, long long old_n, long long new_n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v963; }
